package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/go-chi/chi/v5"
	"myapp/auth"
	"myapp/returns"
)

type NotePayload struct {
	Note string `json:"note"`
}

type ReturnHandler struct {
	Manager returns.Manager
}

func (h *ReturnHandler) AppendRMANote(w http.ResponseWriter, r *http.Request) {
	rmaID := chi.URLParam(r, "rmaID")
	user := auth.CurrentUser(r.Context())

	var body NotePayload
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		http.Error(w, "Invalid body", http.StatusBadRequest)
		return
	}

	err := h.Manager.AddNoteForCustomer(r.Context(), rmaID, user.ID, body.Note)
	if err != nil {
		http.Error(w, "Return not found or unauthorized", http.StatusForbidden)
		return
	}

	w.WriteHeader(http.StatusOK)
}
